import{_ as e,o as s,c as a,a6 as t}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"消息体长度","description":"Transfer-Encoding、Content-Length 与连接关闭——七条成帧规则的判定优先级。","frontmatter":{"title":"消息体长度","description":"Transfer-Encoding、Content-Length 与连接关闭——七条成帧规则的判定优先级。","source":"https://daiw.org/manual/http11/message-body-length"},"headers":[],"relativePath":"manual/computer-programming/http11/message-body-length.md","filePath":"manual/computer-programming/http11/message-body-length.md"}'),o={name:"manual/computer-programming/http11/message-body-length.md"};function r(i,n,d,c,l,p){return s(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="消息体长度" tabindex="-1">消息体长度 <a class="header-anchor" href="#消息体长度" aria-label="Permalink to &quot;消息体长度&quot;">​</a></h1><p>消息体长度<strong>不由空行决定</strong>，而由下面这条七步判定链决定。RFC 9112 §6.3 规定接收方 <strong>MUST</strong> 按顺序求值，命中即停。</p><h2 id="判定链" tabindex="-1">判定链 <a class="header-anchor" href="#判定链" aria-label="Permalink to &quot;判定链&quot;">​</a></h2><ol><li><strong>响应对应 HEAD 请求，或状态码为 <code>1xx</code>/<code>204</code>/<code>304</code></strong> → 无消息体。头里即使有 <code>Content-Length</code> 也<strong>不读体</strong>（该值描述的是「若是 GET 会返回多长」）。</li><li><strong>响应对应 CONNECT 且为 <code>2xx</code></strong> → 无消息体；连接自此转为隧道，后续字节不再按 HTTP 解析。</li><li><strong>存在 <code>Transfer-Encoding</code></strong>： <ul><li>若最后一个编码是 <code>chunked</code> → 按分块解码确定长度。</li><li>若 <code>chunked</code> 不在最后（或不存在）→ 响应：读到连接关闭为止；<strong>请求：MUST 返回 400 并关闭连接</strong>（无法确定边界，走私风险）。</li></ul></li><li><strong>存在多个 <code>Content-Length</code>，或单个含多个值且不一致</strong> → <strong>MUST</strong> 拒绝（400 / 502）。</li><li><strong>存在合法单一 <code>Content-Length</code></strong> → 该十进制值即长度。</li><li><strong>请求</strong> → 无消息体（请求不能靠连接关闭定界）。</li><li><strong>响应</strong> → 读到连接关闭为止。</li></ol><h2 id="transfer-encoding-优先于-content-length" tabindex="-1">Transfer-Encoding 优先于 Content-Length <a class="header-anchor" href="#transfer-encoding-优先于-content-length" aria-label="Permalink to &quot;Transfer-Encoding 优先于 Content-Length&quot;">​</a></h2><p>两者同时出现时：<strong><code>Transfer-Encoding</code> 生效，<code>Content-Length</code> MUST 被视为无效并移除</strong>。这是防走私的关键——但更安全的做法是直接拒绝该报文：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST / HTTP/1.1</span></span>
<span class="line"><span>Host: x</span></span>
<span class="line"><span>Content-Length: 6</span></span>
<span class="line"><span>Transfer-Encoding: chunked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>前端若按 <code>Content-Length</code> 读、后端按 <code>chunked</code> 读，两者对「报文在哪结束」产生分歧，攻击者可把后续字节注入成下一个请求（CL.TE / TE.CL 走私）。规范要求代理<strong>拒绝</strong>此类报文。</p><h2 id="content-length" tabindex="-1">Content-Length <a class="header-anchor" href="#content-length" aria-label="Permalink to &quot;Content-Length&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Length = 1*DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>十进制</strong>，无正负号、无前导 <code>+</code>、不接受十六进制或前导 <code>0x</code>。前导零语法上合法但不应生成。</li><li>单位是<strong>字节</strong>，且是<strong>编码后</strong>（应用 <code>Content-Encoding</code> 之后）的长度。</li><li>值必须与实际体字节数完全一致： <ul><li>实际体<strong>短于</strong>声明 → 接收方视为消息不完整，MUST 当作出错（连接不可复用）。</li><li>实际体<strong>长于</strong>声明 → 多出的字节被当作下一个报文的开头（走私）。</li></ul></li><li>响应可在无体时仍带 <code>Content-Length: 0</code>；HEAD 与 304 的 <code>Content-Length</code> 是元信息，见判定链第 1 条。</li></ul><h2 id="chunked-传输编码" tabindex="-1">chunked 传输编码 <a class="header-anchor" href="#chunked-传输编码" aria-label="Permalink to &quot;chunked 传输编码&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chunked-body = *chunk last-chunk trailer-section CRLF</span></span>
<span class="line"><span>chunk        = chunk-size [ chunk-ext ] CRLF chunk-data CRLF</span></span>
<span class="line"><span>chunk-size   = 1*HEXDIG</span></span>
<span class="line"><span>last-chunk   = 1*(&quot;0&quot;) [ chunk-ext ] CRLF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>一个实例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>Transfer-Encoding: chunked</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7</span></span>
<span class="line"><span>Mozilla</span></span>
<span class="line"><span>9</span></span>
<span class="line"><span>Developer</span></span>
<span class="line"><span>0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>要点：</p><ul><li><strong><code>chunk-size</code> 是十六进制</strong>，大小写不敏感，不带 <code>0x</code>。与十进制的 <code>Content-Length</code> 正好相反，是高频错误点。</li><li><code>chunk-size</code> 不含 CRLF 与 chunk-ext 本身的长度。</li><li>每个 <code>chunk-data</code> 之后<strong>必须</strong>跟 CRLF。</li><li>长度为 0 的块表示结束，其后是可选的 trailer 区，再跟一个 CRLF 收尾。</li><li>解码后的字节流才是真正的消息体；<code>Content-Length</code> 若与之共存则无效。</li></ul><h3 id="chunk-ext" tabindex="-1">chunk-ext <a class="header-anchor" href="#chunk-ext" aria-label="Permalink to &quot;chunk-ext&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chunk-ext = *( BWS &quot;;&quot; BWS ext-name [ BWS &quot;=&quot; BWS ext-val ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>无标准化的扩展名，接收方 <strong>MUST</strong> 忽略不认识的扩展。实践中几乎不用，且部分实现对超长 chunk-ext 有拒绝策略（DoS 防护）。</p><h2 id="编码栈的顺序" tabindex="-1">编码栈的顺序 <a class="header-anchor" href="#编码栈的顺序" aria-label="Permalink to &quot;编码栈的顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transfer-Encoding = #transfer-coding</span></span>
<span class="line"><span>transfer-coding   = token *( OWS &quot;;&quot; OWS transfer-parameter )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>已注册值：<code>chunked</code>、<code>compress</code>、<code>deflate</code>、<code>gzip</code>、<code>trailers</code>（后者仅用于 <code>TE</code>）。</p><ul><li>列表顺序即<strong>应用顺序</strong>：<code>Transfer-Encoding: gzip, chunked</code> 表示先 gzip 再分块；接收方逆序解码。</li><li><code>chunked</code> <strong>MUST</strong> 是请求中的最后一个编码，且<strong>不得</strong>重复出现。</li><li>客户端<strong>不得</strong>向 HTTP/1.0 接收方发送 <code>Transfer-Encoding</code>。</li><li>HTTP/2 与 HTTP/3 中该字段<strong>被禁用</strong>（成帧由协议层负责）。</li></ul><h2 id="transfer-encoding-vs-content-encoding" tabindex="-1">Transfer-Encoding vs Content-Encoding <a class="header-anchor" href="#transfer-encoding-vs-content-encoding" aria-label="Permalink to &quot;Transfer-Encoding vs Content-Encoding&quot;">​</a></h2><p>高频混淆点，二者正交：</p><table tabindex="0"><thead><tr><th></th><th><code>Transfer-Encoding</code></th><th><code>Content-Encoding</code></th></tr></thead><tbody><tr><td>层次</td><td>传输层，逐跳</td><td>表示层，端到端</td></tr><tr><td>是否影响成帧</td><td><strong>是</strong></td><td>否</td></tr><tr><td>是否改变资源本身</td><td>否，接收即还原</td><td><strong>是</strong>，<code>ETag</code> 针对编码后的表示</td></tr><tr><td>代理可否改动</td><td>可以（可重新分块）</td><td><strong>不可</strong></td></tr><tr><td>典型值</td><td><code>chunked</code></td><td><code>gzip</code>、<code>br</code>、<code>zstd</code></td></tr></tbody></table><p><code>Content-Length</code> 计的是 <code>Content-Encoding</code> <strong>之后</strong>、<code>Transfer-Encoding</code> <strong>之前</strong>的长度。</p><h2 id="te-与-trailers" tabindex="-1">TE 与 trailers <a class="header-anchor" href="#te-与-trailers" aria-label="Permalink to &quot;TE 与 trailers&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TE = #t-codings</span></span>
<span class="line"><span>t-codings = &quot;trailers&quot; / ( transfer-coding [ weight ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>客户端用 <code>TE</code> 声明自己能接受哪些传输编码；<code>TE: trailers</code> 表示愿意接收 trailer 区。<code>TE</code> 是逐跳字段，<strong>必须</strong>在 <code>Connection</code> 中列出：<code>Connection: TE</code>。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/connection-management">连接管理</a>——持久连接、Connection 字段与逐跳语义。</p>`,32)])])}const u=e(o,[["render",r]]);export{h as __pageData,u as default};
